import{_ as o,o as e,c as l,ak as s}from"./chunks/framework.DKi5cyCJ.js";const f=JSON.parse('{"title":"RTOS 线程与多轴","description":"按截止时间划分任务、急停不走普通队列、五电机统一运动任务","frontmatter":{"title":"RTOS 线程与多轴","description":"按截止时间划分任务、急停不走普通队列、五电机统一运动任务","date":"2026-10-21T00:00:00.000Z"},"headers":[],"relativePath":"pages/blog/2026-10-21-RTOS线程与多轴.md","filePath":"pages/blog/2026-10-21-RTOS线程与多轴.md"}'),t={name:"pages/blog/2026-10-21-RTOS线程与多轴.md"};function d(i,a,r,c,n,p){return e(),l("div",null,[...a[0]||(a[0]=[s('<h1 id="rtos-线程与多轴" tabindex="-1">RTOS 线程与多轴 <a class="header-anchor" href="#rtos-线程与多轴" aria-label="Permalink to &quot;RTOS 线程与多轴&quot;">​</a></h1><blockquote><p>系列目录：<a href="/pages/blog/2026-10-20-嵌入式驱动面试手册.html">嵌入式驱动面试手册</a>。中断和 API 的分界见 <a href="/pages/blog/2026-10-21-中断优先级与FreeRTOS.html">中断优先级与 FreeRTOS</a>。</p></blockquote><p>按截止时间和失效后果建任务，不要按“一个外设一个任务”来拆。FreeRTOS 里数字越大优先级越高，空闲任务是 0。周期任务用 <code>vTaskDelayUntil</code>，<code>vTaskDelay</code> 不补偿本次执行时间，周期会越漂越长。中断里只清标志、写入环形缓冲、发任务通知。解析、浮点和字符串放到任务里。</p><h2 id="一套五电机业务怎么拆" tabindex="-1">一套五电机业务怎么拆 <a class="header-anchor" href="#一套五电机业务怎么拆" aria-label="Permalink to &quot;一套五电机业务怎么拆&quot;">​</a></h2><p>执行器是 XYZ、内外盘和注射泵，驱动器是 DRV8711（SPI 配置，STEP/DIR 脉冲）。另外有电容采样、CAN 和 RS232。急停可以来自总线命令、FAULT 脚或位置超差。</p><div class="blog-flow"><div class="blog-flow-col"><div class="blog-flow-node accent">SafetyTask<br><small>最高。急停不进普通队列</small></div><div class="blog-flow-down">↓</div><div class="blog-flow-node">MotionTask 1 kHz<br><small>五台电机的曲线和插补</small></div><div class="blog-flow-down">↓</div><div class="blog-flow-node">电容任务 / 业务编排</div><div class="blog-flow-down">↓</div><div class="blog-flow-node">CAN、RS232 只解析并投递</div><div class="blog-flow-down">↓</div><div class="blog-flow-node">日志<br><small>最低。队列满就丢，不能堵住控制</small></div></div></div><p>以 <code>configMAX_PRIORITIES = 32</code> 为例：SafetyTask 31，MotionTask 28，电容任务 26，业务 18，CAN 12，串口 10，日志 2。Safety 和 Motion 不调用会阻塞的 API。</p><p>XYZ 需要同时看三轴，所以用一个 MotionTask 管全部电机，而不是一轴一个任务。1 kHz 里更新梯形或 S 曲线，把频率写进定时器；插补算法见 <a href="/pages/blog/2026-10-21-插补与速度规划.html">插补与速度规划</a>。</p><p>急停在 ISR 里认出来以后，直接给 SafetyTask 发任务通知。FAULT 脚的中断第一件事是拉低使能或 STEP，再通知任务。SafetyTask 把状态锁存在急停，直到收到明确复位。MotionTask 每个周期开头看故障事件，置位就停止发脉冲。</p><p>DRV8711 共用的 SPI 用互斥量，并打开优先级继承。不要在定时器中断里喂狗。电容状态只在变化时置事件位，避免把业务任务叫醒得太勤。</p><p>栈可以按这个量级起步：Safety 1 KB 以内，Motion 2–4 KB，业务 3–4 KB。打开栈溢出检测，上线前看运行时统计。</p><p><a href="/pages/blog/2026-10-20-嵌入式驱动面试手册.html">返回目录</a></p>',12)])])}const S=o(t,[["render",d]]);export{f as __pageData,S as default};
